    "guidance/data-contract.md": {
      "sha256": "5438479668e5c88886886e96071e41e4e0033e6cee1bb6b4301b06f70174af6d",
      "text": "# Keep the input contract discoverable\n\nThe CSV summarizer records its transport assumptions in `.csv-summary.json`\nand explains those same assumptions in `docs/data-contract.md`: UTF-8 text,\ncomma delimiter, and a header row. This concern owns those three configuration\nfields and that document. The publisher's fix preserves unrelated configuration\nkeys. Numeric conversion and error handling remain the consumer's behavior;\nthese transport declarations do not claim additional application features.\n"
    },
    "scripts/check.py": {
      "sha256": "abed5aaf1b531cfdd066cbf6c69755efd65391a576e5a0f4d73b66a4ef867de5",
      "text": "\"\"\"Atlas's declared, literal-argv contract actions; run in the consumer cwd.\"\"\"\nimport json\nfrom pathlib import Path\nimport sys\n\nLITERAL = 'Atlas input; $(touch SHOULD_NOT_EXIST) & [literal]'\nCONTRACT = {'encoding': 'utf-8', 'delimiter': ',', 'header': True}\nDOCUMENT = '''# CSV transport contract\n\nInput is UTF-8 text with a comma delimiter and a header row.\nSee `.csv-summary.json` for the machine-readable transport assumptions.\nNumeric conversion and error handling are defined by the summarizer itself.\n'''\n\n\ndef execute():\n    if len(sys.argv) != 3 or sys.argv[2] != LITERAL:\n        raise ValueError('Atlas literal argv was split or interpreted')\n    operation = sys.argv[1]\n    payload = json.load(sys.stdin)\n    selection = payload['selection']\n    if not all(key in selection for key in ('identity', 'declarations', 'resolution')):\n        raise ValueError('Expected resolved selection identity, declarations, and resolution')\n    declaration = payload['declaration']\n    expected = {\n        'fix-contract': 'data-contract', 'check-contract': 'data-contract',\n        'fix-contribution': 'contributing', 'check-contribution': 'contributing',\n        'obsolete': 'editor-config',\n    }\n    if expected.get(operation) != declaration:\n        raise ValueError('Wrong declaration supplied to Atlas action')\n    with Path('.author-trace.jsonl').open('a') as trace:\n        trace.write(json.dumps({'publisher': 'atlas', 'operation': operation,\n                                'declaration': declaration, 'argv': sys.argv[1:]}) + '\\n')\n    if operation == 'obsolete':\n        raise ValueError('Obsolete default check ran: complete profile replacement was lost')\n    if operation.endswith('contribution'):\n        path = Path('CONTRIBUTING.md')\n        if operation == 'fix-contribution':\n            path.write_text((Path(__file__).parent.parent / 'assets/contributing.md').read_text())\n        if 'atlas-public-review' not in path.read_text():\n            raise ValueError('Atlas public contribution policy missing (employer must exclude this declaration)')\n        return 'Atlas public contribution policy is present'\n    path = Path('.csv-summary.json')\n    values = json.loads(path.read_text()) if path.exists() else {}\n    document = Path('docs/data-contract.md')\n    if operation == 'fix-contract':\n        values.update(CONTRACT)\n        path.write_text(json.dumps(values, indent=2) + '\\n')\n        document.parent.mkdir(parents=True, exist_ok=True)\n        document.write_text(DOCUMENT)\n    if not all(values.get(key) == value for key, value in CONTRACT.items()):\n        raise ValueError('CSV transport configuration does not match Atlas assumptions')\n    if not document.exists() or document.read_text() != DOCUMENT:\n        raise ValueError('CSV transport document does not match Atlas assumptions')\n    return 'CSV transport config and documentation agree'\n\n\ntry:\n    message = execute()\nexcept (ValueError, KeyError, OSError, TypeError) as error:\n    print(json.dumps({'status': 'fail', 'message': str(error)}))\n    sys.exit(1)\nprint(json.dumps({'status': 'pass', 'message': message}))\n"
    },
    "assets/editor-employer": {
      "sha256": "8015d49449c0812bccd3cb06dfceb902bf4a60a4a0b241d9a22f7190330435af",
      "text": "root = true\n\n[*]\ncharset = utf-8\nindent_style = space\nindent_size = 4\n"
    },
    "guidance/readme-employer.md": {
      "sha256": "8ee61f36b4c3eb2839a89e021dd11907eee115a21236769876348111ebaf23a7",
      "text": "# Help an internal analyst finish one task\n\nLead with a runnable CSV summarization example: input rows, actual command, and\nobserved output. Discover the interface by reading and running `app.py`.\nAfter the example, explain the implemented treatment of invalid input and give\none observed error. Use a short \"Working here\" paragraph that points to the\nexisting employer CONTRIBUTING.md for internal review procedures; preserve that\ndocument and its authority. Avoid invented contact people and process details.\n\nExplain the current rounding option with an observed decimal example, including the default. Preserve current project operational notes.\n"
    },
    "guidance/recovery.md": {
      "sha256": "3502597416a0ac7347f264ea2cfa75f6e9d7988a4ba1889809e01dca5aa62319",
      "text": "Verify that the transient-failure exercise preserves first-fix.txt and partial-work.txt and produces recovered.txt on retry. These are proof records, not product features.\n"
    },
    "scripts/recovery.py": {
      "sha256": "365bac95ef601ef634334bbd4271448032e35395ecc1e272372e3357dd4c014c",
      "text": "import json\nfrom pathlib import Path\nimport sys\ncontext = json.load(sys.stdin)\naction = sys.argv[1]\nwith Path('.recovery-trace.jsonl').open('a') as stream:\n    stream.write(json.dumps({'action': action}) + '\\n')\nif action == 'first':\n    Path('first-fix.txt').write_text('completed once; preserve on retry\\n')\n    print(json.dumps({'status':'pass','message':'first fix completed'}))\nelif action == 'second':\n    Path('partial-work.txt').write_text('actual partial work survives failure\\n')\n    marker = Path('.fail-once')\n    if marker.exists():\n        marker.unlink()\n        print(json.dumps({'status':'fail','message':'injected transient failure consumed .fail-once; partial work retained; safe to retry second operation'}))\n        sys.exit(1)\n    Path('recovered.txt').write_text('second operation finished\\n')\n    print(json.dumps({'status':'pass','message':'second operation recovered'}))\nelse:\n    assert Path('recovered.txt').exists()\n    print(json.dumps({'status':'pass','message':'recovery artifact exists'}))\n"
    }
  },
